  // Each zone opens the same assignment popover as the side panels.
  // LT/RT (L2/R2) are not visible on a front view, so they get small
  // labelled tabs at the top corners.
  interface Zone {
    button: string;
    x: number;
    y: number;
    w: number;
    h: number;
    circle?: boolean;
    zoneLabel?: string;
  }

  // Xbox 360 art: inline SVG, viewBox 256 x 175.
  const XBOX_VW = 256;
  const XBOX_VH = 175;
  const xboxZones: Zone[] = [
    { button: "LT", x: 6, y: 1, w: 34, h: 12, zoneLabel: "LT" },
    { button: "RT", x: 216, y: 1, w: 34, h: 12, zoneLabel: "RT" },
    { button: "LB", x: 36, y: 2, w: 60, h: 18 },
    { button: "RB", x: 160, y: 2, w: 60, h: 18 },
    { button: "Back", x: 103, y: 47, w: 14, h: 14, circle: true },
    { button: "Start", x: 140, y: 47, w: 14, h: 14, circle: true },
    { button: "Y", x: 185, y: 28, w: 18, h: 18, circle: true },
    { button: "X", x: 167, y: 45, w: 18, h: 18, circle: true },
    { button: "B", x: 202, y: 45, w: 18, h: 18, circle: true },
    { button: "A", x: 185, y: 62, w: 18, h: 18, circle: true },
    { button: "LeftThumb", x: 43, y: 34, w: 39, h: 39, circle: true },
    { button: "RightThumb", x: 142, y: 73, w: 39, h: 39, circle: true },
    { button: "DPadUp", x: 88, y: 77, w: 13, h: 12 },
    { button: "DPadDown", x: 88, y: 102, w: 13, h: 12 },
    { button: "DPadLeft", x: 76, y: 89, w: 12, h: 13 },
    { button: "DPadRight", x: 101, y: 89, w: 12, h: 13 },
  ];

  // DualShock 4 art: /ds4.svg (native viewBox 268 x 174). L2/R2 are not
  // visible on this front view, so they get labelled tabs at the top
  // corners; the protruding top tabs are L1/R1. Face buttons keep the
  // internal Xbox names: Triangle=Y, Circle=B, Cross=A, Square=X;
  // Share=Back, Options=Start.
  const DS4_VW = 268;
  const DS4_VH = 174;
  const ds4Zones: Zone[] = [
    { button: "LT", x: 2, y: 1, w: 26, h: 12, zoneLabel: "LT" },
    { button: "RT", x: 240, y: 1, w: 26, h: 12, zoneLabel: "RT" },
    { button: "LB", x: 31, y: 0, w: 41, h: 14 },
    { button: "RB", x: 196, y: 0, w: 41, h: 14 },
    { button: "Back", x: 75, y: 19, w: 12, h: 19 },
    { button: "Start", x: 181, y: 19, w: 12, h: 19 },
    { button: "Y", x: 209.5, y: 22.5, w: 18, h: 18, circle: true },
    { button: "X", x: 191, y: 41.5, w: 18, h: 18, circle: true },
    { button: "B", x: 228.5, y: 41.5, w: 18, h: 18, circle: true },
    { button: "A", x: 209.5, y: 60.5, w: 18, h: 18, circle: true },
    { button: "LeftThumb", x: 74, y: 75.5, w: 35, h: 35, circle: true },
    { button: "RightThumb", x: 160, y: 75.5, w: 35, h: 35, circle: true },
    { button: "DPadUp", x: 42.5, y: 29, w: 14.5, h: 15.5 },
    { button: "DPadDown", x: 42.5, y: 58.7, w: 14.5, h: 15.5 },
    { button: "DPadLeft", x: 27, y: 44.5, w: 15.5, h: 14.2 },
    { button: "DPadRight", x: 57, y: 44.5, w: 15.5, h: 14.2 },
  ];

  let isDs4 = $derived($profile.controllerType === "ds4");
  let zones = $derived(isDs4 ? ds4Zones : xboxZones);
  let vw = $derived(isDs4 ? DS4_VW : XBOX_VW);
  let vh = $derived(isDs4 ? DS4_VH : XBOX_VH);
</script>

